package com.bank.risk;

import java.math.BigInteger;
import java.util.*;
import java.util.logging.*;

public class RiskWeightDemo {
    private static final Logger log = Logger.getLogger("RiskWeight");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(1L, "Rajesh", 30),
            new Employee(2L, "Priya", 28),
            new Employee(3L, "Amit", 35)
        );
        RiskWeightService service = new RiskWeightService();
        long product = service.ageProduct(staff);           // guarded long
        BigInteger big = service.ageProductBig(staff);       // overflow-proof
        log.info(() -> "Age product (long, guarded) = " + product);
        log.info(() -> "Age product (BigInteger)     = " + big);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final int age;
    Employee(Long id, String name, int age) { this.id = id; this.name = name; this.age = age; }
    int getAge() { return age; }
}

// ─── Would be in service/RiskWeightService.java ───
class RiskWeightService {
    // identity 1L (NEVER 0). multiplyExact throws on overflow instead of wrapping silently.
    long ageProduct(List<Employee> employees) {
        return employees.stream()
            .mapToLong(Employee::getAge)
            .reduce(1L, Math::multiplyExact);
    }

    // Overflow-proof alternative using BigInteger (three-arg reduce for parallel safety).
    BigInteger ageProductBig(List<Employee> employees) {
        return employees.stream()
            .reduce(BigInteger.ONE,
                    (acc, e) -> acc.multiply(BigInteger.valueOf(e.getAge())),
                    BigInteger::multiply);
    }
}
